const eta=p=>{const actual=(p.visits||[]).filter(v=>v.timed&&Number.isFinite(+v.time)&&+v.time>0).slice(0,5).map(v=>+v.time).sort((a,b)=>a-b);return actual.length?Math.max(1,Math.round(actual[Math.floor(actual.length/2)])):(+S?.set?.defaultCutMinutes||33)};
const competitivePrice=p=>{const sqft=Math.max(0,+p.sqft||0);if(sqft<=5000)return 40;if(sqft<=10000)return 55;if(sqft<=15000)return 70;if(sqft<=20000)return 85;return Math.round((85+Math.ceil((sqft-20000)/5000)*15)/5)*5};
