function setSyncState(v){CLOUD_SYNC=v;document.querySelectorAll('[data-sync]').forEach(e=>{e.textContent=v==='saving'?'Syncing…':v==='ok'?'Cloud synced':v==='offline'?'Offline · saved on device':v==='error'?'Sync needs retry':'Local';e.className='sync-pill '+(v==='ok'?'ok':v==='error'||v==='offline'?'warn':'')})}
