async function syncCloudWorkspace(){if(!authToken()||!BIZ_ACCOUNT||!navigator.onLine){setSyncState('offline');return false}try{const d=await authRequest('/api/workspace',{method:'PUT',body:JSON.stringify({workspace:S})});if(d.workspace){S=d.workspace;fix();try{localStorage.setItem(workspaceKey(),JSON.stringify(S))}catch(e){}}else if(d.updatedAt)S.cloudUpdatedAt=d.updatedAt;setSyncState('ok');return true}catch(e){console.warn('Cloud sync failed',e);setSyncState('error');return false}}
