async function pullCloudWorkspace(force=false){if(!authToken()||!BIZ_ACCOUNT||!navigator.onLine||cloudSaveTimer||CLOUD_SYNC==='saving')return false;try{const cloud=await fetchCloudWorkspace();if(!cloud)return false;const remote=Date.parse(cloud.cloudUpdatedAt||0)||0,local=Date.parse(S?.cloudUpdatedAt||0)||0;if(force||remote>local||((cloud.bp||[]).length>(S?.bp||[]).length)){const mode=S.mode;S=cloud;S.mode=BIZ_ACCOUNT.role==='crew'?'crew':mode;fix();try{localStorage.setItem(workspaceKey(),JSON.stringify(S))}catch(e){}setSyncState('ok');buildNav();render();return true}setSyncState('ok');return false}catch(e){console.warn('Cloud refresh failed',e);return false}}


const cur=()=>S.mode==='cust'&&CUSTOMER_ACCOUNT?.property?CUSTOMER_ACCOUNT.property:S.p[S.sel];
const GRASS={'Unknown':{lo:3,hi:4},'Kentucky bluegrass':{lo:3,hi:4},'Tall fescue':{lo:3,hi:4},'Fine fescue':{lo:3,hi:4},'Perennial ryegrass':{lo:3,hi:4},'Zoysiagrass':{lo:1.5,hi:2.5}};
function shapePattern(p){let pts=[];try{const rings=parcelRings(p.parcel);if(rings.length)pts=rings[0].map(q=>[q[1],q[0]]);else{const z=(p.zones||[]).find(z=>z.type==='mow'&&z.pts?.length>=3);if(z)pts=z.pts}}catch(e){}if(pts.length<3)return P[0];const lat=pts.reduce((a,q)=>a+q[0],0)/pts.length,lng=pts.reduce((a,q)=>a+q[1],0)/pts.length,kx=111320*Math.cos(lat*Math.PI/180),ky=110540,xy=pts.map(q=>[(q[1]-lng)*kx,(q[0]-lat)*ky]);let xx=0,yy=0,xyc=0;for(const q of xy){xx+=q[0]*q[0];yy+=q[1]*q[1];xyc+=q[0]*q[1]}let deg=(Math.atan2(2*xyc,xx-yy)*90/Math.PI+180)%180;const choices=[{d:0,p:P[1]},{d:45,p:P[2]},{d:90,p:P[0]},{d:135,p:P[3]}];return choices.sort((a,b)=>Math.min(Math.abs(deg-a.d),180-Math.abs(deg-a.d))-Math.min(Math.abs(deg-b.d),180-Math.abs(deg-b.d)))[0].p}
function patternAdvice(p){const recent=p.visits.slice(0,Math.max(2,S.set.rot||3)),shape=shapePattern(p),scores=P.map((name,index)=>{const matches=p.visits.filter(v=>v.pattern===name).slice(0,5),quality=matches.length?matches.reduce((s,v)=>s+(Number(v.cov)||0)-(Number(v.ov)||0)*.5,0)/matches.length:0;const shapeBoost=!p.visits.length&&name===shape?16:0;return{name,score:(matches.length?quality*.12:10)+shapeBoost-(recent[0]?.pattern===name?18:0)-recent.slice(1).reduce((s,v,i)=>s+(v.pattern===name?9/(i+1):0),0)-index*.001,matches}}).sort((a,b)=>b.score-a.score);
const best=scores[0],last=recent[0],prior=best.matches,notes=[];if(last)notes.push('Last cut '+dt(last.date)+' used '+last.pattern+'; change direction to limit repeated wheel tracks.');else notes.push('First-cut direction is aligned to the mapped property shape, then TurfOS rotates future cuts to reduce repeated wheel tracks.');if(prior.length)notes.push('This direction averaged '+Math.round(avg(prior,'cov'))+'% coverage and '+Math.round(avg(prior,'ov'))+'% overlap over '+prior.length+' logged cut'+(prior.length===1?'':'s')+'.');else if(p.parcel)notes.push('The mowing passes are generated automatically from the parcel and mapped exclusions.');return{pattern:best.name,notes}}
const rec=p=>patternAdvice(p).pattern;
