function mapHTML(p,h,pat){const plan=cutPlan(p),hasTurf=!plan.draft&&p.zones.some(z=>z.type==='mow'&&z.pts.length>=3),isEdit=h>400,dirIcon=pat.includes('Vertical')?'↑':pat.includes('Horizontal')?'→':pat.includes('45°')?'↗':'↖';return`<div style="display:flex;align-items:center;gap:10px;margin:0 0 10px;padding:10px 12px;border:1px solid var(--line);border-radius:12px;background:rgba(18,58,38,.08)"><div style="width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:#123a26;color:#fff;font:bold 26px/1 sans-serif;box-shadow:0 2px 8px #0003">${dirIcon}</div><div><div class="small" style="font-weight:800;text-transform:uppercase;letter-spacing:.08em">Cut Direction</div><strong style="font-size:16px">${pat}</strong></div></div><div class="map" id="${isEdit?'emap':'dmap'}" style="height:${h}px;${isEdit&&view3d?'display:none':''}"></div>${isEdit?`<div class="map" id="scene3d" style="height:${h}px;${view3d?'':'display:none'}"></div>`:''}<div class="legend"><span><i class="dot" style="background:${plan.draft?'#facc15':'#fff'}"></i>${plan.loading?'Checking houses':plan.draft?'Draft passes — verify turf':plan.zones.length?'Planned passes':'No passes yet'}: ${pat}</span><span><i class="dot" style="background:#38bdf8"></i>Parcel boundary</span><span><i class="dot" style="background:#4ade80"></i>Mowing zone</span><span><i class="dot" style="background:#f87171"></i>No-cut / obstacle</span><span><i class="dot" style="background:#fb923c"></i>Weed-whack zone</span></div>${(p.obstacles||[]).some(o=>o.source==='microsoft')?'<div class="small">Building footprints © Microsoft (ODbL).</div>':''}`+(plan.loading?'<div class="small" style="margin-top:8px">Checking building footprints and driveways before drawing cut lines…</div>':hasTurf?'<div class="small" style="margin-top:8px">White passes follow the traced turf and stop at mapped obstacles and no-cut areas. Check aerial imagery and on-site conditions for missing hazards.</div>':plan.draft?'<div class="small" style="margin-top:8px">The green provisional mow area follows the GIS property line. Amber detected and red confirmed structure cutouts are previewed in the yellow passes. Check the entire area on satellite imagery; the parcel can include beds and other non-grass surfaces.</div>':`<div class="small" style="margin-top:8px">${p.lat?plan.lookupFailed?'House lookup unavailable; automatic draft paused. Retry mapped buildings or mark the house as No-cut.':plan.houseMissing?'No house footprint found. Mark the house as No-cut before drawing automatic lines.':plan.roofReview?'Roof outline needs review. Provisional lines are shown with the mapped roof removed; confirm or retrace it before field use.':plan.large?'Parcel too large for a draft; trace the grass to map passes.':p.parcel?'Draft hidden. Use Show draft lines or trace the grass.':'A parcel is needed for automatic draft lines, or trace the grass to draw cut lines.':'Add the address, then trace the grass on the Property Map to draw a cut pattern.'}</div>`)}
function toggleMowSource(){const p=cur();if(!p.parcel)return toast('Load a parcel first');const hasTrace=p.zones.some(z=>z.type==='mow'&&z.pts.length>=3);if(!hasTrace)return toast('Property line is already the mowing area');p.manualMowOverride=!p.manualMowOverride;p.useParcelMow=!p.manualMowOverride;p.autoLines=true;if(p.useParcelMow)syncParcelArea(p);else resz(p);save();render();toast(p.useParcelMow?'Property line is the mowing area':'Using traced lawn instead')}
