function stopSim(){clearInterval(sim.t);sim.t=null}
function tickCut(){stopSim();sim.t=setInterval(simUI,1000)}
function cutMs(c=S.activeCut){return c?Math.max(0,c.elapsedMs||0)+(c.startedAt?Math.max(0,Date.now()-c.startedAt):0):0}
function timedProperty(c=S.activeCut){return c&&S.bp.find(p=>String(p.id)===String(c.propertyId))}
function startRoute(){if(S.activeCut)return toast('Finish or cancel the active cut first');S.activeCut={mode:S.mode,propertyId:cur().id,startedAt:Date.now(),elapsedMs:0,startedOn:today()};save();tickCut();simUI();toast('Cut timer started')}
function pauseCut(){const c=S.activeCut;if(!c||!c.startedAt)return;c.elapsedMs=cutMs(c);c.startedAt=null;save();simUI()}
function resumeCut(){const c=S.activeCut;if(!c||c.startedAt)return;c.startedAt=Date.now();save();tickCut();simUI()}
function cancelCut(){if(!S.activeCut||!confirm('Discard this unfinished cut timer?'))return;S.activeCut=null;stopSim();save();simUI();toast('Timer discarded')}
function finishRoute(){const c=S.activeCut,p=timedProperty(c);if(!p)return toast('No active cut');const ms=mowerSetting();openM(`<h2>Finish cut · ${esc(p.name)}</h2><div class="small">Elapsed: <strong id="cutElapsed">${(cutMs()/60000).toFixed(1)} min</strong>. Time continues until you save. Pause it first if the crew is stopped.</div><div class="form" style="margin-top:14px"><label>Pattern<select id="tc_pat">${P.map(x=>`<option${x===rec(p)?' selected':''}>${x}</option>`).join('')}</select></label><label>Cut height<input id="tc_h" value="${esc(S.set.h)}"></label><div class="small">Active mower: <strong>${esc(activeMower()?.name||'Not configured')}</strong> · Deck setting: <strong>${esc(ms.label)}</strong></div><label>Estimated coverage % (crew input)<input id="tc_cov" type="number" min="0" max="100" value="96"></label><label>Estimated overlap % (crew input)<input id="tc_ov" type="number" min="0" max="100" value="8"></label>${proofPhotoHTML('tc_photo')}</div><div class="actions"><button class="btn" onclick="closeM()">Keep timing</button><button class="btn primary" onclick="saveTimedCut()">Save service + proof</button></div>`)}
async function saveTimedCut(){const c=S.activeCut,p=timedProperty(c);if(!p)return toast('No active cut');const photo=await proofFromInput('tc_photo');if(photoRequired(photo))return toast('Take a completion photo before finishing the yard');const ms=cutMs(c),cov=Math.min(100,Math.max(0,+$('tc_cov').value||0)),ov=Math.min(100,Math.max(0,+$('tc_ov').value||0)),v={date:today(),pattern:$('tc_pat').value,height:$('tc_h').value,time:Math.max(.1,Math.round(ms/6000)/10),durationMs:ms,timed:true,cov,ov,weather:'Not recorded',startedOn:c.startedOn,proofPhoto:photo,mowerId:activeMower()?.id||'',mowerSetting:mowerSetting(parseFloat($('tc_h').value)||targetHeight()).label};S.activeCut=null;stopSim();closeM();p.visits.unshift(v);p.visits.sort((a,b)=>b.date.localeCompare(a.date));rt=null;save();render();afterJobCompleted(p,v);toast('Service saved with completion proof for '+p.name)}
