function addressParts(q){const first=q.split(',')[0].trim().toUpperCase(),match=first.match(/^(\d+[A-Z]?)\s+(.+)$/);if(!match)return null;const words=match[2].replace(/[^A-Z0-9 ]/g,' ').split(/\s+/).filter(Boolean),suffixes=['ST','STREET','RD','ROAD','AVE','AVENUE','DR','DRIVE','BLVD','BOULEVARD','LN','LANE','CT','COURT','PL','PLACE','WAY','CIR','CIRCLE'];if(suffixes.includes(words.at(-1)))words.pop();const dir=['N','S','E','W','NE','NW','SE','SW'];if(dir.includes(words[0]))words.shift();return words.length?{number:match[1],street:words.join(' '),city:(q.split(',')[1]||'').trim().toUpperCase()}:null}
async function countyAddress(q){const parts=addressParts(q),otherState=q.match(/,\s*([A-Z]{2})(?:\s+\d{5})?\s*$/i)?.[1]?.toUpperCase();if(!parts||(otherState&&otherState!=='OH'))return null;const u=new URL(SUMMIT_ADDRESSES+'/query');u.search=new URLSearchParams({f:'json',where:`ADDR_NUM = '${parts.number}' AND COUNTY = 'SUM'`,outFields:'ADDR_NUM,STR_NAME,CITY,COUNTY',returnGeometry:'true',outSR:'4326',resultRecordCount:'200'}).toString();const response=await fetchT(u,{},7000);if(!response.ok)throw Error('County address service unavailable');const data=await response.json();if(data.error)throw Error(data.error.message);const matches=(data.features||[]).filter(f=>(f.attributes?.STR_NAME||'').toUpperCase().replace(/[^A-Z0-9 ]/g,' ').trim()===parts.street&&Number.isFinite(f.geometry?.x)&&Number.isFinite(f.geometry?.y));matches.sort((a,b)=>Number((b.attributes?.CITY||'').toUpperCase()===parts.city)-Number((a.attributes?.CITY||'').toUpperCase()===parts.city));return matches.length?{lat:matches[0].geometry.y,lng:matches[0].geometry.x,source:'county GIS'}:null}
async function geo(q){try{const county=await countyAddress(q);if(county)return county}catch(e){console.warn('County address lookup failed',e)}const response=await fetchT('https://nominatim.openstreetmap.org/search?format=json&limit=1&q='+encodeURIComponent(q),{},7000);if(!response.ok)throw Error('Address search failed');const r=await response.json();return r.length?{lat:+r[0].lat,lng:+r[0].lon,source:'general geocoder'}:null}
async function findAddr(){const q=$('addr').value.trim();if(!q)return;const p=cur();toast('Searching…');try{const r=await geo(q);if(!r)return toast('Address not found');p.lat=r.lat;p.lng=r.lng;p.addr=q;p.street=q;p.geoSource=r.source;p.parcel=null;p.parcelId='';p.obstacles=[];p.autoLines=true;p.obstacleLookupFailed=false;p.houseMissing=false;obstacleLoading.add(p);save();render();await fillParcel(p);if(p.parcel)await findObstacles(p);else{obstacleLoading.delete(p);render();toast('Location set — trace the lawn to draw passes')}}catch(e){obstacleLoading.delete(p);render();toast('Address lookup failed — check the network connection')}}
