function parcelGeometry(g){if(!g||!['Polygon','MultiPolygon'].includes(g.type))return null;const rings=g.type==='Polygon'?g.coordinates.flat():g.coordinates.flat(2);if(!rings.length||rings.length>3000||rings.some(c=>!Array.isArray(c)||c.length<2||!Number.isFinite(c[0])||!Number.isFinite(c[1])||Math.abs(c[0])>180||Math.abs(c[1])>90))return null;return {type:g.type,coordinates:g.coordinates}}
