const parcelRefreshes=new WeakSet();async function refreshParcelIfStale(p=cur()){if(!p?.parcel||parcelRefreshes.has(p))return;const age=Date.now()-(p.parcelFetchedAt||0);if(age<6*60*60*1000)return;parcelRefreshes.add(p);try{await fillParcel(p);await findObstacles(p)}finally{parcelRefreshes.delete(p)}}

function clearParcel(){cur().parcel=null;cur().parcelLabel='';cur().parcelId='';save();render();toast('Boundary removed')}
function parcelRings(g){try{if(!g||!Array.isArray(g.coordinates))return[];if(g.type==='Polygon'){const r=g.coordinates[0];return Array.isArray(r)&&r.length>=3?[r]:[]}if(g.type==='MultiPolygon')return g.coordinates.map(poly=>Array.isArray(poly)&&Array.isArray(poly[0])?poly[0]:null).filter(r=>Array.isArray(r)&&r.length>=3);return[]}catch(e){console.warn('Invalid parcel geometry',e);return[]}}
