function roofBuffer(roof){const pts=roof.pts||[];if(pts.length<3)return roof;const lat=pts[0][0],lng=pts[0][1],kx=111320*Math.cos(lat*Math.PI/180),ky=110540,cloud=pts.flatMap(q=>Array.from({length:8},(_,i)=>[(q[1]-lng)*kx+1.2*Math.cos(i*Math.PI/4),(q[0]-lat)*ky+1.2*Math.sin(i*Math.PI/4)]));cloud.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);const turn=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]),lower=[],upper=[];for(const q of cloud){while(lower.length>1&&turn(lower.at(-2),lower.at(-1),q)<=0)lower.pop();lower.push(q)}for(const q of cloud.slice().reverse()){while(upper.length>1&&turn(upper.at(-2),upper.at(-1),q)<=0)upper.pop();upper.push(q)}return{...roof,pts:lower.slice(0,-1).concat(upper.slice(0,-1)).map(q=>[lat+q[1]/ky,lng+q[0]/kx])}}
