function showBusinessAuth(tab='login'){const g=$('authgate');if(!g)return;g.classList.add('on');document.querySelector('.sidebar').style.visibility='hidden';document.querySelector('main').style.visibility='hidden';$('authpanel').innerHTML=tab==='signup'?`<div class="eyebrow">Create business workspace</div><h1>Start using TurfOS</h1><div class="small">Your company name will automatically brand the business dashboard, customer portal and invoices.</div><div class="tabs"><button class="btn" onclick="showBusinessAuth('login')">Sign in</button><button class="btn primary">Create account</button></div><div id="autherr" class="autherr"></div><div class="form"><label>Company name *<input id="au_company" autocomplete="organization" placeholder="Evergreen Lawn Care" oninput="updateAuthBrandPreview(this.value)"></label><label>Owner / manager name *<input id="au_owner" autocomplete="name" placeholder="Jordan Smith"></label><label>Business email *<input id="au_email" type="email" autocomplete="email" placeholder="you@company.com"></label><label>Phone<input id="au_phone" type="tel" autocomplete="tel" placeholder="(330) 555-0123"></label><label>Primary service area<input id="au_area" placeholder="Macedonia / Summit County, OH"></label><label>Password *<input id="au_password" type="password" autocomplete="new-password" minlength="8" placeholder="At least 8 characters"></label></div><div class="actions"><button class="btn primary" onclick="businessSignup()">Create business account</button></div><div class="authnote">TurfOS account profiles and shared company data are stored in your Cloudflare D1 database, with a local copy kept for field use.</div>`:`<div class="eyebrow">Business account</div><h1>Welcome back</h1><div class="small">Sign in to open your company's TurfOS workspace.</div><div class="tabs"><button class="btn primary">Sign in</button><button class="btn" onclick="showBusinessAuth('signup')">Create account</button></div><div id="autherr" class="autherr"></div><div class="form"><label>Email<input id="au_email" type="email" autocomplete="email" placeholder="you@company.com"></label><label>Password<input id="au_password" type="password" autocomplete="current-password"></label></div><div class="actions"><button class="btn primary" onclick="businessLogin()">Sign in</button></div><div class="authnote">Use the email and password created for this business account.</div>`;updateAuthBrandPreview(tab==='signup'?'':activeBrandName())}
function hideBusinessAuth(){$('authgate')?.classList.remove('on');document.querySelector('.sidebar').style.visibility='';document.querySelector('main').style.visibility=''}
async function switchBusinessWorkspace(profile){BIZ_ACCOUNT=profile;const key='turfos-workspace-v1:'+businessId();let next=null;try{next=JSON.parse(localStorage.getItem(key))}catch(e){}const cloud=await fetchCloudWorkspace();if(cloud)next=cloud;if(!next)next=freshBusinessWorkspace(profile);S=next;S.mode=profile.role==='crew'?'crew':'biz';fix();S.set.businessName=profile.companyName||S.set.businessName;if(profile.role!=='crew')S.set.businessEmail=profile.email||S.set.businessEmail;try{localStorage.setItem(key,JSON.stringify(S))}catch(e){}updateBusinessBrand();if(!cloud&&profile.role!=='crew')queueCloudSave();setSyncState(cloud?'ok':navigator.onLine?'saving':'offline')}
async function businessSignup(){authError();const data={companyName:$('au_company').value.trim(),ownerName:$('au_owner').value.trim(),email:$('au_email').value.trim(),phone:$('au_phone').value.trim(),serviceArea:$('au_area').value.trim(),password:$('au_password').value};if(!data.companyName||!data.ownerName||!data.email||!data.password)return authError('Company name, owner name, email and password are required.');try{const d=await authRequest('/api/auth/signup',{method:'POST',body:JSON.stringify(data)});localStorage.setItem(AUTH_TOKEN_KEY,d.token);await switchBusinessWorkspace(d.account);hideBusinessAuth();buildNav();render();go('dashboard');toast('Business account created')}catch(e){authError(e.message)}}
