function accountCard(){if(!BIZ_ACCOUNT)return'';return`<div class="card"><div class="st"><h2>Business account</h2>${B('Signed in')}</div><div class="sl"><span>Company</span><strong>${esc(BIZ_ACCOUNT.companyName)}</strong></div><div class="sl"><span>Owner / manager</span><strong>${esc(BIZ_ACCOUNT.ownerName)}</strong></div><div class="sl"><span>Email</span><strong>${esc(BIZ_ACCOUNT.email)}</strong></div><div class="sl"><span>Phone</span><strong>${esc(BIZ_ACCOUNT.phone||'—')}</strong></div><div class="sl"><span>Service area</span><strong>${esc(BIZ_ACCOUNT.serviceArea||'—')}</strong></div><div class="sl"><span>Company Code</span><strong>${esc(businessCode()||'—')}</strong></div><div class="small" style="margin:-4px 0 10px">Customers do not need to type this code when they use your direct signup link.</div>${isOwner()?`<div style="margin:12px 0;padding:14px;border:1px solid var(--line);border-radius:12px;background:var(--soft)"><strong>Customer signup link</strong><div class="small" style="margin:4px 0 8px">Put this link behind a “Request Service” button on your company website. Every signup is automatically connected to ${esc(BIZ_ACCOUNT.companyName)}.</div><div class="mapbar"><input value="${esc(customerSignupLink())}" readonly onclick="this.select()"><button class="btn primary" onclick="copyCustomerSignupLink()">Copy link</button></div><div class="actions" style="justify-content:flex-start"><button class="btn sm" onclick="copyCustomerWebsiteButton()">Copy website button HTML</button><a class="btn sm" href="${esc(customerSignupLink())}" target="_blank" rel="noopener">Preview signup ↗</a></div></div>`:''}<div class="sl"><span>Role</span><strong>${BIZ_ACCOUNT.role==='crew'?'Crew member':'Owner / admin'}</strong></div><div class="actions">${isOwner()?'<button class="btn" onclick="editBusinessAccount()">Edit company profile</button><button class="btn" onclick="manageCrew()">Manage crew</button>':''}<button class="btn" onclick="businessLogout()">Sign out</button></div></div>`}
