async function saveBusinessAccount(){const patch={companyName:$('ep_company').value.trim(),ownerName:$('ep_owner').value.trim(),phone:$('ep_phone').value.trim(),serviceArea:$('ep_area').value.trim()};if(!patch.companyName||!patch.ownerName)return toast('Company and owner name are required');try{const d=await authRequest('/api/auth/profile',{method:'PATCH',body:JSON.stringify(patch)});BIZ_ACCOUNT=d.account;S.set.businessName=BIZ_ACCOUNT.companyName;S.set.businessEmail=BIZ_ACCOUNT.email;save();updateBusinessBrand();closeM();render();toast('Company profile updated')}catch(e){toast(e.message)}}
async function manageCrew(){if(!isOwner())return;try{const d=await authRequest('/api/auth/crew');const rows=(d.crew||[]).map(c=>`<div class="sl"><span><strong>${esc(c.ownerName)}</strong><br><span class="small">${esc(c.email)}${c.phone?' · '+esc(c.phone):''}</span></span><button class="btn sm" onclick="removeCrew('${c.id}')">Remove</button></div>`).join('')||'<div class="small">No crew accounts yet.</div>';openM(`<h2>Crew accounts</h2><div class="small">Crew members sign in at the same TurfOS app and automatically get the field workspace for this company.</div><div style="margin-top:12px">${rows}</div><div class="actions"><button class="btn" onclick="closeM()">Close</button><button class="btn primary" onclick="newCrewForm()">＋ Add crew member</button></div>`)}catch(e){toast(e.message)}}
function newCrewForm(){openM(`<h2>Add crew member</h2><div class="form"><label>Name<input id="cr_name" autocomplete="name"></label><label>Email<input id="cr_email" type="email" autocomplete="email"></label><label>Phone<input id="cr_phone" type="tel"></label><label>Temporary password<input id="cr_pass" type="password" minlength="8" placeholder="At least 8 characters"></label></div><div class="actions"><button class="btn" onclick="manageCrew()">Back</button><button class="btn primary" onclick="createCrew()">Create crew login</button></div>`)}
async function createCrew(){const d={ownerName:$('cr_name').value.trim(),email:$('cr_email').value.trim(),phone:$('cr_phone').value.trim(),password:$('cr_pass').value};if(!d.ownerName||!d.email||d.password.length<8)return toast('Enter name, email and an 8+ character password');try{await authRequest('/api/auth/crew',{method:'POST',body:JSON.stringify(d)});toast('Crew login created');manageCrew()}catch(e){toast(e.message)}}
async function removeCrew(id){if(!confirm('Remove this crew login?'))return;try{await authRequest('/api/auth/crew?id='+encodeURIComponent(id),{method:'DELETE'});toast('Crew login removed');manageCrew()}catch(e){toast(e.message)}}
const NAV={biz:[['dashboard','▣','Dashboard'],['map','⌖','Property Map'],['history','↻','Mowing History'],['customers','♙','Customers'],['route','➤','Schedule & Routes'],['weather','☁','Weather'],['health','✚','Lawn Health'],['portal','✉','Billing & Invoices'],['procare','✦','TurfOS Intelligence'],['analytics','▥','Analytics'],['settings','⚙','Settings']],crew:[['crew','▣','Today'],['map','⌖','Property Map'],['route','➤','Schedule'],['weather','☁','Weather'],['history','↻','Mow Log']],cust:[['customer','⌂','My Account'],['portal','✉','Invoices & Messages']]};
function buildNav(){let nav=NAV[S.mode]||NAV.biz;if(innerWidth<=640&&S.mode==='biz')nav=[['dashboard','▣','Dashboard'],['map','⌖','Map'],['route','➤','Schedule'],['portal','✉','Billing'],['more','•••','More']];$('nav').innerHTML=nav.map(n=>`<button data-v="${n[0]}">${n[1]} <b>${n[2]}</b></button>`).join('')}
function openMobileMore(){const items=[['history','↻','Mowing History'],['customers','♙','Customers'],['weather','☁','Weather'],['health','✚','Lawn Health'],['procare','✦','TurfOS Intelligence'],['analytics','▥','Analytics'],['settings','⚙','Settings']];openM(`<h2>More business tools</h2><div style="display:grid;gap:8px;margin-top:12px">${items.map(n=>`<button class="btn" style="text-align:left;min-height:48px" onclick="closeM();go('${n[0]}')">${n[1]} &nbsp; ${n[2]}</button>`).join('')}</div><div class="actions"><button class="btn" onclick="closeM()">Close</button></div>`)}
addEventListener('resize',()=>{clearTimeout(window.__navResize);window.__navResize=setTimeout(()=>{if(BIZ_ACCOUNT||CUSTOMER_ACCOUNT)buildNav()},120)});
async function setMode(m){if(!['biz','crew','cust'].includes(m))return;if(BIZ_ACCOUNT?.role==='crew'&&m!=='crew')return toast('Crew accounts use the field workspace');if(m==='cust'&&!CUSTOMER_ACCOUNT){S.mode='cust';showCustomerAuth();return}if((m==='biz'||m==='crew')&&!BIZ_ACCOUNT){S.mode=m;showBusinessAuth('login');return}S.mode=m;save();buildNav();render();updateBusinessBrand();go(m==='cust'?'customer':m==='crew'?'crew':'dashboard');const p=cur();if(m!=='cust'&&p?.parcel&&p.buildingDataVersion!==BUILDING_DATA_VERSION)findObstacles(p)}
const esc=t=>String(t==null?'':t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const shrink=f=>new Promise(r=>{const i=new Image,u=URL.createObjectURL(f);i.onload=()=>{const k=Math.min(1,640/Math.max(i.width,i.height)),c=document.createElement('canvas');c.width=i.width*k;c.height=i.height*k;c.getContext('2d').drawImage(i,0,0,c.width,c.height);URL.revokeObjectURL(u);r(c.toDataURL('image/jpeg',.6))};i.onerror=()=>r(null);i.src=u});
const proofPhotoHTML=(id='job_photo')=>`<label>Job completion photo ${S.set.requireProofPhoto===false?'(optional)':'*'}<input id="${id}" type="file" accept="image/*" capture="environment" onchange="previewProofPhoto(this,'${id}_preview')"><img id="${id}_preview" class="photo-preview" alt="Completion photo preview"></label><div class="small">Take a clear photo of the finished lawn. TurfOS saves it with the service record and invoice as proof of completion.</div>`;
async function previewProofPhoto(input,previewId){const img=$(previewId);if(!img||!input?.files?.[0])return;const data=await shrink(input.files[0]);if(data){img.src=data;img.style.display='block';img.dataset.photo=data}}
async function proofFromInput(id){const input=$(id),preview=$(id+'_preview');if(preview?.dataset?.photo)return preview.dataset.photo;if(input?.files?.[0])return await shrink(input.files[0]);return''}
function photoRequired(photo){return S.set.requireProofPhoto!==false&&!photo}
function targetHeight(){const n=parseFloat(S.set.h);return Number.isFinite(n)?n:3.5}
function parsePositionMap(text){return String(text||'').split(/[,\n;]/).map(x=>x.trim()).filter(Boolean).map(x=>{const m=x.match(/^([^=:]+)\s*[:=]\s*([0-9.]+)$/);return m?{label:m[1].trim(),height:+m[2]}:null}).filter(x=>x&&Number.isFinite(x.height)).sort((a,b)=>a.height-b.height)}
function activeMower(){const a=(S.set.mowers||[]).find(m=>String(m.id)===String(S.set.activeMowerId));return a||(S.set.mowers||[])[0]||null}
function mowerSetting(height=targetHeight(),m=activeMower()){if(!m)return{ok:false,label:'Add mower',height:null,note:'No mower profile'};const map=parsePositionMap(m.positionMap);if(map.length){const best=map.reduce((a,b)=>Math.abs(b.height-height)<Math.abs(a.height-height)?b:a,map[0]);return{ok:true,label:`${best.label} · ${best.height.toFixed(2)}\"`,height:best.height,note:`${m.name||m.makeModel||'Mower'} position ${best.label}`}}const lo=Number.isFinite(+m.min)?+m.min:1,hi=Number.isFinite(+m.max)?+m.max:5,step=Math.max(.05,+m.step||.25),clamped=Math.min(hi,Math.max(lo,height)),nearest=Math.round((clamped-lo)/step)*step+lo,val=Math.min(hi,Math.max(lo,nearest));return{ok:height>=lo&&height<=hi,label:`${val.toFixed(2)}\"`,height:val,note:height<lo?`Target is below ${m.name||'mower'} minimum ${lo}\"`:height>hi?`Target is above ${m.name||'mower'} maximum ${hi}\"`:`Nearest ${step}\" deck increment`}}
function mowerForm(id=null){const m=id?(S.set.mowers||[]).find(x=>String(x.id)===String(id)):null;openM(`<h2>${m?'Edit':'Add'} mower</h2><div class="form"><label>Mower name<input id="mw_name" value="${esc(m?.name||'')}" placeholder="Crew 1 zero-turn"></label><label>Make / model<input id="mw_model" value="${esc(m?.makeModel||'')}" placeholder="Optional"></label><div class="grid three"><label>Minimum height (in)<input id="mw_min" type="number" step="0.05" value="${m?.min??1.5}"></label><label>Maximum height (in)<input id="mw_max" type="number" step="0.05" value="${m?.max??4.5}"></label><label>Height step (in)<input id="mw_step" type="number" step="0.05" value="${m?.step??0.25}"></label></div><label>Numbered/notched positions (optional)<textarea id="mw_map" rows="3" placeholder="1=1.5, 2=2.0, 3=2.5">${esc(m?.positionMap||'')}</textarea></label><div class="small">If your mower uses numbered/notched positions, enter the real measured inches for each position. That mapping overrides the generic min/max/step calculation.</div></div><div class="actions"><button class="btn" onclick="closeM()">Cancel</button><button class="btn primary" onclick="saveMower('${m?.id||''}')">Save mower</button></div>`)}
function saveMower(id=''){const name=$('mw_name').value.trim()||'Mower',makeModel=$('mw_model').value.trim(),min=+$('mw_min').value,max=+$('mw_max').value,step=+$('mw_step').value,positionMap=$('mw_map').value.trim();if(!Number.isFinite(min)||!Number.isFinite(max)||min>=max||!Number.isFinite(step)||step<=0)return toast('Check mower height range and step');S.set.mowers=S.set.mowers||[];let m=S.set.mowers.find(x=>String(x.id)===String(id));if(m)Object.assign(m,{name,makeModel,min,max,step,positionMap});else{m={id:'MW-'+Date.now(),name,makeModel,min,max,step,positionMap};S.set.mowers.push(m);S.set.activeMowerId=m.id}save();closeM();render();toast('Mower profile saved')}
function setActiveMower(id){S.set.activeMowerId=id;save();render();toast('Active mower updated')}
function deleteMower(id){if(!confirm('Remove this mower profile?'))return;S.set.mowers=(S.set.mowers||[]).filter(m=>String(m.id)!==String(id));if(String(S.set.activeMowerId)===String(id))S.set.activeMowerId=S.set.mowers[0]?.id||'';save();render()}
const weatherPlanCache={};
async function scheduleForecast(p){if(!coord(p))return null;const key=p.id,c=weatherPlanCache[key];if(c&&Date.now()-c.t<15*60e3)return c.data;const r=await fetchT(`https://api.open-meteo.com/v1/forecast?latitude=${p.lat}&longitude=${p.lng}&daily=precipitation_probability_max,precipitation_sum,wind_speed_10m_max,temperature_2m_max&forecast_days=14&precipitation_unit=inch&wind_speed_unit=mph&temperature_unit=fahrenheit&timezone=auto`,{},9000);if(!r.ok)throw 0;const data=await r.json();weatherPlanCache[key]={t:Date.now(),data};return data}
function forecastRisk(data,date){if(!data?.daily)return{bad:false,reason:'No forecast'};const i=data.daily.time.indexOf(date);if(i<0)return{bad:false,reason:'Forecast unavailable'};const prob=+(data.daily.precipitation_probability_max?.[i]||0),rain=+(data.daily.precipitation_sum?.[i]||0),wind=+(data.daily.wind_speed_10m_max?.[i]||0),bad=prob>=(+S.set.weatherRainProb||60)||rain>=(+S.set.weatherRainIn||.20)||wind>=(+S.set.weatherWindMax||28);const parts=[];if(prob>=(+S.set.weatherRainProb||60))parts.push(prob+'% rain chance');if(rain>=(+S.set.weatherRainIn||.20))parts.push(rain.toFixed(2)+'\" rain');if(wind>=(+S.set.weatherWindMax||28))parts.push(Math.round(wind)+' mph wind');return{bad,prob,rain,wind,reason:parts.join(' · ')||'Acceptable forecast'}}
async function applyWeatherDelays(){const key=monday(dateAdd(today(),weekOffset*7)),plan=weeklyPlan(key),start=weekOffset?0:Math.max(0,dayDiff(today(),key));toast('Checking weather for scheduled yards…');const props=S.bp.filter(p=>Number.isInteger(plan.days[String(p.id)])&&!p.visits.some(v=>v.date>=key&&v.date<=dateAdd(key,6)));const forecasts={};await Promise.all(props.map(async p=>{try{forecasts[p.id]=await scheduleForecast(p)}catch(e){forecasts[p.id]=null}}));plan.weatherNotes=plan.weatherNotes||{};let moved=0,flagged=0;for(const p of props){const id=String(p.id);if(plan.manual?.[id])continue;const from=plan.days[id],risk=forecastRisk(forecasts[p.id],dateAdd(key,from));if(!risk.bad){delete plan.weatherNotes[id];continue}let target=null,targetRisk=null;for(let d=Math.max(from+1,start);d<=6;d++){const r=forecastRisk(forecasts[p.id],dateAdd(key,d));if(r.bad)continue;const assigned=S.bp.filter(q=>String(q.id)!==id&&plan.days[String(q.id)]===d&&!q.visits.some(v=>v.date>=key&&v.date<=dateAdd(key,6))),minutes=assigned.reduce((n,q)=>n+eta(q),0)+eta(p)+routeOrder(assigned.concat(p)).drive;if(minutes<=(+S.set.dailyHours||8)*60){target=d;targetRisk=r;break}}if(target!=null){plan.days[id]=target;plan.weatherNotes[id]={from,to:target,reason:risk.reason,at:new Date().toISOString()};moved++}else{plan.weatherNotes[id]={from,to:from,reason:risk.reason+' · no open safer day this week',at:new Date().toISOString(),flag:true};flagged++}}save();rt=null;renderRoute();drawRouteMap();toast(`${moved} weather move${moved===1?'':'s'}${flagged?' · '+flagged+' flagged':''}`)}
function weatherNoteFor(plan,p){const n=plan?.weatherNotes?.[String(p.id)];if(!n)return'';return`<div class="weather-note">☔ ${n.flag?'Weather risk:':'Weather moved:'} ${esc(n.reason)}${!n.flag&&n.to!==n.from?' → '+DAY[n.to]:''}</div>`}
function proofRate(p){const v=(p.visits||[]).slice(0,10);return v.length?Math.round(v.filter(x=>x.proofPhoto).length/v.length*100):0}

const dsl=p=>p.visits[0]?Math.round((Date.now()-new Date(p.visits[0].date+'T12:00'))/864e5):null;
const dueB=q=>{const d=dsl(q);return d===null?B('New','w'):d<=0?B('Mowed'):d>10?B('Overdue','w'):d>=7?B('Due','w'):B('OK')};
function hAdv(p){const v=p.visits[0],cut=parseFloat(S.set.h)||3.5;if(!v)return'Log your first mow to start height tracking.';const d=Math.max(0,dsl(p)),last=parseFloat(v.height)||cut,est=last+Math.min(d,14)*.15,rm=(est-cut)/est;
return`Last cut at ${v.height}, ${d} day${d==1?'':'s'} ago. Estimated grass height ~${est.toFixed(1)}" (rough growth model). `+(rm>1/3?`Cutting to ${cut}" would remove ${Math.round(rm*100)}%, over the one-third rule — raise the deck to about ${(est*2/3).toFixed(1)}" now and lower it in 3–5 days.`:`Cutting to ${cut}" removes ${Math.max(0,Math.round(rm*100))}% — within the one-third rule.`)}
const wxc={};
function fetchWx(p){const k=p.lat+','+p.lng,c=wxc[k];if(c&&Date.now()-c.t<6e5)return c.p;const pr=fetchT(`https://api.open-meteo.com/v1/forecast?latitude=${p.lat}&longitude=${p.lng}&current=temperature_2m,relative_humidity_2m,wind_speed_10m,precipitation&hourly=soil_moisture_0_to_1cm&daily=precipitation_sum,precipitation_probability_max,temperature_2m_max&past_days=3&forecast_days=3&temperature_unit=fahrenheit&wind_speed_unit=mph&precipitation_unit=inch&timezone=auto`,{},8000).then(r=>{if(!r.ok)throw 0;return r.json()});wxc[k]={t:Date.now(),p:pr};pr.catch(()=>delete wxc[k]);return pr}
function verdict(p,w){const c=w.current,d=w.daily,h=w.hourly,i=h.time.indexOf(c.time.slice(0,13)+':00'),sm=i>=0?h.soil_moisture_0_to_1cm[i]:null,y=d.precipitation_sum[2]||0,pop=d.precipitation_probability_max[3]||0,ds=dsl(p),bad=[],warn=[];
if(c.precipitation>0)bad.push('It is raining now');if(c.srain>.25)bad.push(c.srain.toFixed(2)+'" of rain recorded today');if(pop>=60)bad.push(pop+'% chance of rain today');if(y>.25)bad.push(y.toFixed(2)+'" of rain yesterday — lawn likely wet');if(sm!==null&&sm>.4)bad.push('Soil surface is very wet');
if(c.wind_speed_10m>20)warn.push('Windy — clippings and debris will scatter');if(c.temperature_2m>90)warn.push('Hot — mow early morning or evening');if(c.temperature_2m<45)warn.push('Cool — growth is slow, mowing may not be needed');
if(ds!==null&&ds<3)warn.push(`Only ${ds} day${ds==1?'':'s'} since the last cut`);
return{v:bad.length?['Wait','w']:ds!==null&&ds<3?['Not yet','w']:['Yes — good time to mow',''],bad,warn,sm}}
function wxHTML(p,w,st){if(st)w={...w,current:{...w.current,temperature_2m:st.temp,relative_humidity_2m:st.hum,wind_speed_10m:st.wind,precipitation:st.raining?1:0,srain:st.rain}};const c=w.current,d=w.daily,V=verdict(p,w),f=n=>(+n||0).toFixed(2),L2=[...V.bad,...V.warn];
return`<div class="card rec"><div class="st"><h2>Should I mow today?</h2>${B(V.v[0],V.v[1])}</div>${L2.map(x=>`<div class="sl"><span>${x}</span></div>`).join('')||'<div class="sl"><span>Conditions look good and the lawn is due.</span></div>'}<div class="small" style="margin-top:8px">${hAdv(p)}</div></div>
<div class="card" style="margin-top:16px"><div class="st"><h2>Live conditions</h2><span class="small">${st?st.src+' station · '+new Date(st.t).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}):'Open-Meteo'}</span></div><div class="sl"><span>Temperature / humidity</span><strong>${Math.round(c.temperature_2m)}°F · ${c.relative_humidity_2m}%</strong></div><div class="sl"><span>Wind</span><strong>${Math.round(c.wind_speed_10m)} mph${st?' (gust '+Math.round(st.gust)+')':''}</strong></div>${st?`<div class="sl"><span>Rain today (station)</span><strong>${st.rain.toFixed(2)}"</strong></div>`:''}<div class="sl"><span>Soil moisture (surface, modeled)</span><strong>${V.sm===null?'n/a':Math.round(V.sm*100)+'%'}</strong></div><div class="sl"><span>Rain last 3 days</span><strong>${f(d.precipitation_sum.slice(0,3).reduce((a,b)=>a+b,0))}"</strong></div><div class="sl"><span>Rain next 2 days</span><strong>${f(d.precipitation_sum[4]+d.precipitation_sum[5])}"</strong></div></div>
<div class="card" style="margin:16px 0"><div class="st"><h2>Recent and upcoming</h2></div><table><thead><tr><th>Day</th><th>High</th><th>Rain</th><th>Chance</th></tr></thead><tbody>${d.time.map((t,i)=>`<tr><td>${dt(t)}${i<3?' (past)':i==3?' (today)':''}</td><td>${Math.round(d.temperature_2m_max[i])}°F</td><td>${f(d.precipitation_sum[i])}"</td><td>${d.precipitation_probability_max[i]==null?'—':d.precipitation_probability_max[i]+'%'}</td></tr>`).join('')}</tbody></table></div>`}
async function loadWx(id){const e=$(id);if(!e)return;const p=cur();if(!p.lat){e.innerHTML='<div class="card small" style="margin-bottom:16px">Set the address on the Map tab to get live weather and your mow-today verdict.</div>';return}e.innerHTML='<div class="card small">Loading live weather…</div>';try{const w=await fetchWx(p);let st=null;try{st=await fetchStation()}catch(x){}if($(id)===e)e.innerHTML=wxHTML(p,w,st)}catch(x){e.innerHTML='<div class="card small">Weather unavailable (offline or blocked).</div>'}}
function renderWx(){const st=S.st||{},p=cur(),auto=!st.type;$('weather').innerHTML=`<div class="top"><div><div class="eyebrow">Weather intelligence</div><h1>Weather</h1></div><div class="topright">${propSelect()}</div></div><div id="wx_w"></div>
<div class="grid two" style="margin-top:16px"><div class="card"><div class="st"><h2>Automatic weather</h2>${B(auto?'Ready':'Backup ready')}</div><div class="sl"><span>Weather source</span><strong>${auto?'Property location':'Personal station + property forecast'}</strong></div><div class="sl"><span>Property</span><strong>${esc(p.addr||p.street||p.name)}</strong></div><div class="small" style="margin-top:8px">No weather-station setup is required. TurfOS automatically uses each property's mapped latitude/longitude for live conditions and scheduling forecasts. Add a personal station only if you want on-site sensor readings.</div>${st.type?`<div class="actions"><button class="btn" onclick="useAutomaticWeather()">Use automatic weather only</button></div>`:''}</div>
<div class="card"><div class="st"><h2>Weather delay rules</h2>${B('Active')}</div><div class="form"><label>Delay if rain chance is at least<input id="wr_prob" type="number" min="0" max="100" step="5" value="${+S.set.weatherRainProb||60}"><span class="small">%</span></label><label>Delay if forecast rain is at least<input id="wr_rain" type="number" min="0" max="5" step="0.05" value="${+S.set.weatherRainIn||.20}"><span class="small">inches</span></label><label>Delay if wind reaches<input id="wr_wind" type="number" min="0" max="80" step="1" value="${+S.set.weatherWindMax||28}"><span class="small">mph</span></label></div><div class="small">These rules control the Schedule & Routes → Apply weather delays button. Completed jobs and manually moved jobs stay locked.</div><div class="actions"><button class="btn primary" onclick="saveWeatherRules()">Save delay rules</button></div></div></div>
<details class="card" style="margin-top:16px" ${st.type?'open':''}><summary style="cursor:pointer;font-weight:800">Optional personal weather station ${st.type?'· connected':''}</summary><div style="margin-top:14px"><div class="small" style="margin-bottom:10px">Only use this if your company already owns a Tempest or Weather Underground station. Otherwise leave this section alone—automatic property weather is already working.</div><div class="form"><label>Provider<select id="st_t">${[['','Choose a station provider'],['tempest','Tempest / WeatherFlow'],['wu','Weather Underground PWS']].map(o=>`<option value="${o[0]}"${o[0]==(st.type||'')?' selected':''}>${o[1]}</option>`).join('')}</select></label><label>Station ID<input id="st_i" value="${esc(st.id)}" placeholder="Paste station ID"></label><label>API token / key<input id="st_k" type="password" value="${esc(st.key)}" placeholder="Paste token or API key"></label></div><div class="small" style="margin-top:8px">TurfOS tests the connection when you save it. Credentials stay in this browser only.</div><div class="actions"><button class="btn primary" onclick="saveStation()">Connect & test station</button>${st.type?'<button class="btn" onclick="useAutomaticWeather()">Disconnect station</button>':''}</div></div></details>`}
function saveGrass(value){if(!GRASS[value])return;cur().grass=value;save();render();toast('Grass type updated')}
function lawnPlan(p,w){const grass=GRASS[p.grass]?p.grass:'Unknown',range=GRASS[grass],last=p.visits[0],choice=patternAdvice(p),issues=p.probs.filter(x=>!x.done),todayKey=w?.current?.time?.slice(0,10),d=w?.daily,i=d?.time?.indexOf(todayKey)??-1,wet=w?.current?.precipitation>0,hot=w?.current?.temperature_2m>=90,heavy=i>=0&&(Number(d.precipitation_sum[i-1])||0)>.25,days=i>=0?d.time.slice(i,i+3).map((date,j)=>({date,rain:Number(d.precipitation_sum[i+j])||0,pop:Number(d.precipitation_probability_max[i+j])||0})):[],next=days.find(x=>x.pop<40&&x.rain<.1),notes=[];
notes.push(...choice.notes);notes.push(grass==='Unknown'?`Grass type is unknown; identify it to tailor cut height. Start near ${range.lo}–${range.hi} inches for cool-season turf.`:`For ${grass}, consider ${range.lo}–${range.hi} inches and avoid removing more than one third of the blade in one cut.`);if(wet||heavy)notes.push('Wet turf or recent rain: postpone mowing until leaves and ground are firm.');else if(hot)notes.push('Heat forecast: mow when cooler and avoid mowing visibly stressed turf.');if(issues.length)notes.push(`${issues.length} open problem area${issues.length===1?'':'s'}: inspect before cutting and avoid routing equipment through damaged turf.`);if(last&&Number(last.cov)<94)notes.push('Last cut coverage was below 94%; review missed areas and exclusions on the map.');if(last&&Number(last.ov)>15)notes.push('Last cut had high overlap; check stripe spacing on the map.');
return{grass,range,pattern:choice.pattern,notes,window:!w?'Forecast unavailable; check the yard before mowing.':wet||heavy?'Wait for the lawn to dry; check again on site.':next?`Possible dry window: ${dt(next.date)} (${next.pop}% rain chance in daily forecast). Confirm conditions on site.`:'No low-rain day in the next 3 forecast days; check again later.',history:`${p.visits.length} logged cut${p.visits.length===1?'':'s'} · ${last?'last '+dt(last.date):'no prior cut'}`}}
function healthPlanHTML(p,w){const a=lawnPlan(p,w);return`<div class="card rec" style="margin-bottom:16px"><div class="st"><h2>Personalized next-cut plan</h2>${B(a.history)}</div><div class="form"><label>Grass type<select onchange="saveGrass(this.value)">${Object.keys(GRASS).map(g=>`<option${g===a.grass?' selected':''}>${g}</option>`).join('')}</select></label></div><div class="big">${a.pattern}</div><div class="small">${a.window}</div>${a.notes.map(n=>`<div class="sl"><span>${esc(n)}</span></div>`).join('')}<div class="small" style="margin-top:10px">Planning aid based on your logged cuts and a modeled local forecast. Inspect grass type, moisture and obstacles on site; no image-based disease diagnosis is performed.</div><button class="btn" style="margin-top:10px" onclick="go('map')">See stripes on map</button></div>`}
