async function deliverInvoice(p,v,manual=false){
 if(!p.email){v.delivery='needs-email';v.deliveryNote='Add customer email';save();render();if(manual)toast('Add a customer email first');return false}
 let endpoint='';try{endpoint=invoiceEndpoint(S.set.invoiceEmailEndpoint||'/api/send-invoice')}catch(e){v.delivery='error';v.deliveryNote=e.message;save();render();if(manual)toast(e.message);return false}
 const payload={event:'invoice.created',customer:{id:p.id,name:p.name,email:p.email,address:p.street},invoice:{id:v.id,date:v.date,description:v.desc,amount:+v.amt,status:v.paid?'paid':'unpaid'},business:{name:S.set.businessName||'TurfOS Lawn Care',email:S.set.businessEmail||''},paymentLink:S.set.paymentLink||'',message:invoiceText(p,v),proofPhotoDataUrl:v.proofPhoto||'',mowerSetting:v.mowerSetting||''};
 if(endpoint){
  v.delivery='sending';v.deliveryNote='Sending email';save();render();
  try{
   const r=await fetchT(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)},15000);
   const data=await r.json().catch(()=>({}));
   if(!r.ok)throw new Error(data.error||('HTTP '+r.status));
   v.delivery='sent';v.sentAt=new Date().toISOString();v.deliveryNote='Emailed automatically'+(data.id?' · '+data.id:'');save();render();toast('Invoice emailed to '+p.email);return true;
  }catch(e){console.warn('Automatic invoice email failed',e);let m=(e&&e.message)?String(e.message):'Email server failed';if(/failed to fetch/i.test(m))m='Cannot reach email server. Open the hosted TurfOS https:// site and verify _worker.js is deployed.';v.delivery='error';v.deliveryNote=m.slice(0,220);save();render();if(manual)toast('Invoice email failed: '+v.deliveryNote)}
 }
 const hook=(S.set.invoiceWebhook||'').trim();
 if(hook){
  v.delivery='sending';save();render();
  try{const r=await fetchT(hook,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)},10000);if(!r.ok)throw new Error('HTTP '+r.status);v.delivery='sent';v.sentAt=new Date().toISOString();v.deliveryNote='Sent through fallback webhook';save();render();toast('Invoice sent to '+p.email);return true}catch(e){console.warn('Invoice webhook failed',e);v.delivery='error';v.deliveryNote='Delivery failed';save();render()}
 }
 if(manual){const subject=encodeURIComponent(`Invoice ${v.id} from ${S.set.businessName||'TurfOS Lawn Care'}`),body=encodeURIComponent(invoiceText(p,v));location.href=`mailto:${encodeURIComponent(p.email)}?subject=${subject}&body=${body}`;toast('Automatic email is not configured — opened your email app instead')}
 return false
}
