function renderPortal(){if(S.mode==='cust'&&!customerRecord()){$('portal').innerHTML='<div class="card"><h2>Customer sign in required</h2><p class="small">Return to the customer login to access invoices and messages.</p></div>';return}const p=cur(),biz=S.mode==='biz',me=biz?'biz':'cust',suggested=competitivePrice(p),effective=priceFor(p);$('portal').innerHTML=`<div class="top"><div><div class="eyebrow">${biz?'Customer billing':'Your customer portal'}</div><h1>${biz?'Billing & Invoices':'Invoices & Messages'}</h1></div><div class="topright">${biz?propSelect():''}${biz?'<button class="btn primary" onclick="invForm()">＋ New invoice</button>':''}</div></div>
${biz?`<div class="grid two" style="margin-bottom:16px"><div class="card"><div class="st"><h2>Automatic invoicing</h2>${B(p.autoInvoice===false?'Off':'On',p.autoInvoice===false?'w':'')}</div><div class="form"><label>Customer email<input id="bill_email" type="email" value="${esc(p.email)}" placeholder="customer@example.com"></label><label>Price for this property ($)<input id="bill_price" type="number" min="0" step="1" value="${p.customPrice||''}" placeholder="${suggested}"></label><label><input id="bill_auto" type="checkbox" ${p.autoInvoice===false?'':'checked'}> Create and send an invoice after each completed job</label></div><div class="small">Recommended price for ${(+p.sqft||0).toLocaleString()} ft²: <strong>$${suggested}</strong> per cut. Current invoice price: <strong>$${effective}</strong>. Leave the property price blank to use automatic size-based pricing.</div><div class="actions"><button class="btn primary" onclick="saveBilling()">Save billing</button></div></div><div class="card"><h2>Delivery status</h2><div class="sl"><span>Automatic invoice creation</span><strong>${S.set.autoInvoice===false?'Disabled in Settings':'Enabled'}</strong></div><div class="sl"><span>Email delivery</span><strong>${S.set.invoiceEmailEndpoint?'Automatic email endpoint':'Manual fallback'}</strong></div><div class="sl"><span>Reply-to email</span><strong>${esc(S.set.businessEmail||'Add in Settings')}</strong></div><div class="sl"><span>Payment link</span><strong>${S.set.paymentLink?'Configured':'Not configured'}</strong></div><div class="small" style="margin-top:10px">When a mowing service is saved as complete, TurfOS creates the invoice immediately. TurfOS sends the invoice through the secure email endpoint configured in Settings. If that fails, the optional webhook is used as a fallback.</div></div></div>`:''}
<div class="grid two" style="margin-top:0"><div class="card"><div class="st"><h2>Invoices · ${esc(p.name)}</h2></div><table><thead><tr><th>Date</th><th>Description</th><th>Amount</th><th>Payment</th><th>Delivery</th><th></th></tr></thead><tbody>${p.inv.map(v=>`<tr><td>${dt(v.date)}</td><td>${esc(v.desc)}${v.proofPhoto?`<div class="proof-wrap"><img class="proof-shot" src="${v.proofPhoto}" alt="Completed lawn proof"><span class="small">📷 Job completion proof${v.mowerSetting?'<br>Deck '+esc(v.mowerSetting):''}</span></div>`:''}</td><td>$${(+v.amt).toFixed(2)}</td><td>${v.paid?B('Paid'):B('Unpaid','w')}</td><td>${v.delivery==='sent'?B('Sent'):v.delivery==='error'?B('Failed','w'):v.delivery==='needs-email'?B('Need email','w'):B('Queued','w')}${v.deliveryNote?`<div class="small" style="max-width:220px;margin-top:4px">${esc(v.deliveryNote)}</div>`:''}</td><td>${biz?`<button class="btn sm" onclick="togInv('${v.id}')">${v.paid?'Unpay':'Mark paid'}</button> <button class="btn sm" onclick="sendInvoiceNow('${v.id}')">${v.delivery==='sent'?'Resend':'Send'}</button>`:(!v.paid&&S.set.paymentLink?`<a class="btn sm primary" href="${esc(S.set.paymentLink)}" target="_blank" rel="noopener">Pay now ↗</a>`:'')}</td></tr>`).join('')||'<tr><td colspan="6">No invoices yet. Completing a job will create one automatically.</td></tr>'}</tbody></table></div>
<div class="card"><div class="st"><h2>Messages</h2></div><div style="max-height:320px;overflow:auto;display:grid;gap:8px">${p.msgs.map(m=>`<div style="justify-self:${m.from===me?'end':'start'};max-width:85%;background:${m.from===me?'var(--green)':'var(--soft)'};color:${m.from===me?'#fff':'inherit'};padding:8px 12px;border-radius:12px;font-size:13px">${esc(m.t)}<div style="font-size:10px;opacity:.7">${m.from==='biz'?'Provider':'Customer'} · ${dt(m.date)}</div></div>`).join('')||'<div class="small">No messages yet.</div>'}</div><div class="mapbar" style="margin:12px 0 0"><input id="mt" placeholder="Write a message…" onkeydown="if(event.key==='Enter')sendMsg()"><button class="btn primary" onclick="sendMsg()">Send</button></div></div></div>`}
function invForm(){openM(`<h2>New invoice · ${esc(cur().name)}</h2><div class="form"><label>Description<input id="iv_d" value="Lawn mowing service"></label><label>Amount ($)<input id="iv_a" type="number" value="${priceFor(cur())}"></label></div><div class="actions"><button class="btn" onclick="closeM()">Cancel</button><button class="btn primary" onclick="saveInv()">Create</button></div>`)}
function saveInv(){const v={id:'INV-'+Date.now().toString().slice(-8),date:today(),desc:$('iv_d').value,amt:+$('iv_a').value||0,paid:false,delivery:'queued'};cur().inv.unshift(v);save();closeM();render();toast('Invoice created')}
function sendInvoiceNow(id){const p=cur(),v=p.inv.find(x=>x.id===id);if(v)deliverInvoice(p,v,true)}
function togInv(id){const v=cur().inv.find(x=>x.id===id);v.paid=!v.paid;save();render()}
async function sendMsg(){const t=$('mt').value.trim();if(!t)return;if(S.mode==='cust'){try{const d=await customerRequest('/api/customer/message',{method:'POST',body:JSON.stringify({text:t})});CUSTOMER_ACCOUNT=normalizeCustomerAccount(d.customer);render();toast('Message sent')}catch(e){toast(e.message)}return}cur().msgs.push({from:'biz',t,date:today()});save();render()}
/* ---------- Weather station sync ---------- */
let stc=null;
async function fetchStation(){const s=S.st;if(!s||!s.type||!s.id||!s.key)return null;if(stc&&Date.now()-stc.t<12e4&&stc.k===s.type+s.id)return stc.v;let v;
if(s.type==='tempest'){const o=(await(await fetch(`https://swd.weatherflow.com/swd/rest/observations/station/${encodeURIComponent(s.id)}?token=${encodeURIComponent(s.key)}`)).json()).obs[0];v={temp:o.air_temperature*9/5+32,hum:o.relative_humidity,wind:(o.wind_avg||0)*2.23694,gust:(o.wind_gust||0)*2.23694,rain:(o.precip_accum_local_day||0)/25.4,raining:(o.precip||0)>0,t:o.timestamp*1000,src:'Tempest'}}
else{const o=(await(await fetch(`https://api.weather.com/v2/pws/observations/current?stationId=${encodeURIComponent(s.id)}&format=json&units=e&apiKey=${encodeURIComponent(s.key)}`)).json()).observations[0],i=o.imperial;v={temp:i.temp,hum:o.humidity,wind:i.windSpeed||0,gust:i.windGust||0,rain:i.precipTotal||0,raining:i.precipRate>0,t:Date.parse(o.obsTimeUtc),src:'Weather Underground'}}
if(isNaN(v.temp))throw 0;stc={t:Date.now(),k:s.type+s.id,v};return v}
function saveWeatherRules(){const prob=Math.max(0,Math.min(100,+$('wr_prob').value||60)),rain=Math.max(0,+$('wr_rain').value||.20),wind=Math.max(0,+$('wr_wind').value||28);S.set.weatherRainProb=prob;S.set.weatherRainIn=rain;S.set.weatherWindMax=wind;save();toast('Weather delay rules saved');renderWx();loadWx('wx_w')}
function useAutomaticWeather(){S.st={type:'',id:'',key:''};stc=null;save();renderWx();loadWx('wx_w');toast('Automatic property weather enabled')}
async function saveStation(){const type=$('st_t')?.value||'',id=$('st_i')?.value.trim()||'',key=$('st_k')?.value.trim()||'';if(!type)return toast('Choose Tempest or Weather Underground');if(!id||!key)return toast('Enter the station ID and API token/key');const previous=S.st;S.st={type,id,key};stc=null;try{const v=await fetchStation();save();toast('Station connected: '+Math.round(v.temp)+'°F · '+Math.round(v.hum)+'% humidity');renderWx();loadWx('wx_w')}catch(e){S.st=previous||{};stc=null;toast('Station test failed — automatic property weather is still active');renderWx();loadWx('wx_w')}}
/* ---------- Route planner ---------- */
let rt=null,rsel=null,rst='me',rwatch=null,rme=null;
const gps=()=>new Promise((ok,no)=>navigator.geolocation?navigator.geolocation.getCurrentPosition(p=>ok(p.coords),no,{enableHighAccuracy:true,timeout:8000}):no());
const hav=(a,b)=>{const r=x=>x*Math.PI/180,h=Math.sin(r(b.lat-a.lat)/2)**2+Math.cos(r(a.lat))*Math.cos(r(b.lat))*Math.sin(r(b.lng-a.lng)/2)**2;return 12742e3*Math.asin(Math.sqrt(h))};
const mi=m=>(m/1609.34).toFixed(1),mn=s=>Math.round(s/60);
function nnRoute(pts){const o=[pts[0]],rest=pts.slice(1);while(rest.length){const l=o[o.length-1];rest.sort((a,b)=>hav(l,a)-hav(l,b));o.push(rest.shift())}return{ord:o,geo:o.map(q=>[q.lat,q.lng]),legs:o.slice(1).map((q,i)=>{const d=hav(o[i],q)*1.3;return{d,t:d/15.6}}),src:'estimate'}}
/* A stable calendar-week assignment, recalculated on rollover or on request. */
let weekOffset=0,weekDay=0;
const DAY=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
function dateAdd(key,n){const d=new Date(key+'T12:00');d.setDate(d.getDate()+n);return d.toLocaleDateString('en-CA')}
function dayDiff(a,b){return Math.round((Date.parse(a+'T12:00Z')-Date.parse(b+'T12:00Z'))/864e5)}
function monday(key){const d=new Date(key+'T12:00'),i=(d.getDay()+6)%7;return dateAdd(key,-i)}
const coord=p=>Number.isFinite(+p.lat)&&Number.isFinite(+p.lng)&&p.lat!=null&&p.lng!=null&&(+p.lat!==0||+p.lng!==0);
function routeOrder(props){const mapped=props.filter(coord),missing=props.filter(p=>!coord(p));if(!mapped.length)return{order:missing,miles:0,drive:0};const depot=S.set.depot,origin=depot&&coord(depot)?depot:null;
const length=arr=>arr.slice(1).reduce((sum,p,i)=>sum+hav(arr[i],p),0)+(origin&&arr.length?hav(origin,arr[0]):0);
let best=null;for(const first of (origin?[null]:mapped)){const remaining=mapped.slice(),order=[];let at=origin||first;if(first){order.push(first);remaining.splice(remaining.indexOf(first),1)}while(remaining.length){remaining.sort((a,b)=>hav(at,a)-hav(at,b));at=remaining.shift();order.push(at)}if(!best||length(order)<length(best))best=order}
let changed=true;while(changed){changed=false;for(let i=0;i<best.length-1;i++)for(let j=i+1;j<best.length;j++){const trial=best.slice();trial.splice(i,j-i+1,...best.slice(i,j+1).reverse());if(length(trial)+.01<length(best)){best=trial;changed=true}}}
const meters=length(best)*1.3;return{order:best.concat(missing),miles:meters/1609.34,drive:Math.round(meters/15.6/60)}}
function weeklyPlan(key){S.weekPlans=S.weekPlans||{};let plan=S.weekPlans[key];if(!plan||!plan.days||typeof plan.days!=='object'){plan={days:{}};S.weekPlans[key]=plan}
const ids=new Set(S.bp.map(p=>String(p.id)));Object.keys(plan.days).forEach(id=>{if(!ids.has(id))delete plan.days[id]});const start=dayDiff(key,monday(today()))===0?Math.max(0,dayDiff(today(),key)):0,available=Array.from({length:7-start},(_,i)=>i+start);const work=available.filter(d=>d<5);const choices=work.length?work:available;
const completed=p=>p.visits.some(v=>v.date>=key&&v.date<=dateAdd(key,6));const prior=S.weekPlans[dateAdd(key,-7)]?.days||{};
for(const p of S.bp){if(completed(p))continue;const id=String(p.id);if(Number.isInteger(plan.days[id])&&plan.days[id]>=start&&plan.days[id]<=6)continue;delete plan.days[id];const last=p.visits.filter(v=>v.date<key).map(v=>v.date).sort().pop(),priorDay=prior[id],priorDate=Number.isInteger(priorDay)?dateAdd(key,-7+priorDay):null,reference=last&&last>=dateAdd(key,-7)?last:priorDate&&(!last||priorDate>last)?priorDate:last,due=reference?dateAdd(reference,7):null,pref=Number.isInteger(p.serviceDay)&&p.serviceDay>=0&&p.serviceDay<=6?p.serviceDay:(Number.isInteger(priorDay)?priorDay:null);
let best=choices[0],score=Infinity;for(const d of choices){const date=dateAdd(key,d),assigned=S.bp.filter(q=>String(q.id)!==id&&plan.days[String(q.id)]===d&&!completed(q)),before=routeOrder(assigned),after=routeOrder(assigned.concat(p));const minutes=assigned.reduce((s,q)=>s+eta(q),0)+eta(p)+after.drive,capacity=(+S.set.dailyHours||8)*60,excess=Math.max(0,minutes-capacity),early=due?Math.max(0,dayDiff(due,date)):0,late=due?Math.max(0,dayDiff(date,due)):0;const cost=excess*3+early*70+late*18+(pref==null?0:Math.abs(d-pref)*16)+(after.drive-before.drive)*2+minutes*.02;if(cost<score){score=cost;best=d}}plan.days[id]=best}
save();return plan}
function weekData(){const key=monday(dateAdd(today(),weekOffset*7)),plan=weeklyPlan(key),days=DAY.map((label,d)=>{const date=dateAdd(key,d),done=S.bp.filter(p=>p.visits.some(v=>v.date===date)),pending=S.bp.filter(p=>!p.visits.some(v=>v.date>=key&&v.date<=dateAdd(key,6))&&plan.days[String(p.id)]===d),route=routeOrder(pending);return{label,date,done,pending,route,minutes:pending.reduce((n,p)=>n+eta(p),0)+route.drive}});return{key,days,plan}}
function weekShift(n){weekOffset=Math.max(0,Math.min(1,weekOffset+n));weekDay=0;rt=null;renderRoute();drawRouteMap()}
function weekRebuild(){const key=monday(dateAdd(today(),weekOffset*7));delete S.weekPlans[key];delete S.weekPlans[dateAdd(key,7)];save();rt=null;renderRoute();drawRouteMap();toast('Weekly schedule rebuilt')}
function weekMove(id,day){const p=S.bp.find(q=>String(q.id)===String(id)),key=monday(dateAdd(today(),weekOffset*7));if(!p||(+day<dayDiff(today(),key)&&weekOffset===0)||p.visits.some(v=>v.date>=key&&v.date<=dateAdd(key,6)))return;const plan=weeklyPlan(key);plan.days[String(id)]=+day;plan.manual=plan.manual||{};plan.manual[String(id)]=true;if(plan.weatherNotes)delete plan.weatherNotes[String(id)];rt=null;save();renderRoute();drawRouteMap()}
function weekPreference(id,value){const p=S.bp.find(q=>String(q.id)===String(id));if(!p)return;p.serviceDay=value==='auto'?null:+value;save();weekRebuild()}
function weekHours(value){S.set.dailyHours=Math.min(12,Math.max(1,+value||8));save();renderRoute();drawRouteMap()}
async function saveDepot(){const address=$('depotAddr').value.trim();if(!address){delete S.set.depot;save();renderRoute();drawRouteMap();return toast('Starting address cleared')}try{const point=await geo(address);if(!point)throw 0;S.set.depot={address,lat:point.lat,lng:point.lng};save();renderRoute();drawRouteMap();toast('Starting address saved')}catch(e){toast('Could not locate the starting address')}}
function showWeekDay(d){weekDay=d;const {days}=weekData(),props=days[d].route.order.filter(coord);rsel={};props.forEach(p=>rsel[p.id]=true);rst=S.set.depot?'depot':'first';rt=null;renderRoute();drawRouteMap()}
function routeWeekDay(){const {days}=weekData(),props=days[weekDay].route.order.filter(coord);if(!props.length)return toast('Add mapped addresses to plan a route');const depot=S.set.depot,pts=props.map(p=>({p,lat:+p.lat,lng:+p.lng}));if(depot&&coord(depot))pts.unshift({depot:1,lat:+depot.lat,lng:+depot.lng});rt={ord:pts,geo:pts.map(q=>[q.lat,q.lng]),legs:pts.slice(1).map((q,i)=>{const d=hav(pts[i],q)*1.3;return{d,t:d/15.6}}),src:'estimate'};renderRoute();drawRouteMap();toast('Estimated daily route shown; use Optimize route for roads')}
async function optRoute(){const stops=S.bp.filter(p=>p.lat&&rsel[p.id]);if(!stops.length)return toast('Select at least one stop');const pts=stops.map(p=>({p,lat:p.lat,lng:p.lng}));
if(rst==='me'){try{const g=await gps();pts.unshift({me:1,lat:g.latitude,lng:g.longitude})}catch(e){return toast('Location unavailable — allow location access or start from the first stop')}}
if(rst==='depot'){const d=S.set.depot;if(!d||!coord(d))return toast('Save a valid starting address first');pts.unshift({depot:1,lat:+d.lat,lng:+d.lng})}
if(pts.length<2)return toast('Select at least 2 stops or start from your location');toast('Optimizing route…');
try{const r=await(await fetchT(`https://router.project-osrm.org/trip/v1/driving/${pts.map(q=>q.lng+','+q.lat).join(';')}?source=first&roundtrip=false&overview=full&geometries=geojson`,{},9000)).json();if(r.code!=='Ok')throw 0;
const ord=r.waypoints.map((w,i)=>({i,k:w.waypoint_index})).sort((a,b)=>a.k-b.k).map(o=>pts[o.i]),t=r.trips[0];rt={ord,geo:t.geometry.coordinates.map(c=>[c[1],c[0]]),legs:t.legs.map(l=>({d:l.distance,t:l.duration})),src:'road'}}
catch(e){rt=nnRoute(pts);toast('Road routing unavailable — showing a straight-line estimate')}
renderRoute();drawRouteMap()}
function rtSum(){const o=rt.ord,D=rt.legs.reduce((s,l)=>s+l.d,0),T=rt.legs.reduce((s,l)=>s+l.t,0),M=o.filter(q=>q.p).reduce((s,q)=>s+eta(q.p),0);
return`<div class="card" style="margin-top:16px"><div class="st"><h2>${rt.src==='road'?'Road-optimized route':'Estimated route'}</h2><span class="small">${mi(D)} mi · ${mn(T)} min driving · ~${M} min mowing · ~${((mn(T)+M)/60).toFixed(1)} hrs total</span></div>${o.map((q,i)=>`<div class="sl"><span><strong>${i+1}.</strong> ${q.me?'Your location (start)':q.depot?'Crew start':esc(q.p.name)}${i&&rt.legs[i-1]?` <span class="small">· ${mi(rt.legs[i-1].d)} mi, ${mn(rt.legs[i-1].t)} min drive</span>`:''}</span><span>${q.me||q.depot?'':`<a class="small" style="color:var(--green)" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination=${q.lat},${q.lng}&travelmode=driving">➤ Navigate</a>`}</span></div>`).join('')}</div>`}
function renderRoute(){const w=weekData(),selected=w.days[weekDay];if(!rsel){rsel={};selected.route.order.forEach(p=>rsel[p.id]=true)}const remaining=w.days.reduce((s,d)=>s+d.pending.length,0),finished=w.days.reduce((s,d)=>s+d.done.length,0);
$('route').innerHTML=`<div class="top"><div><div class="eyebrow">Crew logistics</div><h1>Schedule & Routes</h1></div><div class="topright"><button class="btn" onclick="weekShift(-1)" ${weekOffset?'':'disabled'}>← This week</button><button class="btn" onclick="weekShift(1)" ${weekOffset?'disabled':''}>Next week →</button><button class="btn" onclick="weekRebuild()">↻ Rebuild remaining</button><button class="btn primary" onclick="applyWeatherDelays()">☔ Apply weather delays</button></div></div>
<div class="card"><div class="st"><h2>${dt(w.key)} – ${dt(dateAdd(w.key,6))}</h2><span class="small">${finished} completed · ${remaining} planned · ${S.bp.length} properties</span></div><div class="mapbar"><label class="small">Crew hours per day <input type="number" min="1" max="12" step="0.5" style="width:85px" value="${S.set.dailyHours||8}" onchange="weekHours(this.value)"></label><label class="small" style="flex:1;min-width:200px">Crew start address <input id="depotAddr" style="width:100%" placeholder="Optional: shop or crew starting point" value="${esc(S.set.depot?.address)}"></label><button class="btn" onclick="saveDepot()">Save start</button></div><div class="small">Each property gets one planned slot per calendar week. Automatic scheduling groups nearby properties while balancing crew hours and the last service date. Each day is ordered for a shorter estimated drive; use Optimize route on roads for live road routing before dispatch. Logged services count as completed. Weather delays use each property address automatically—no weather station is required. They move unfinished jobs forward only; manual moves are pinned until the week is rebuilt.</div></div>
<div class="grid three">${w.days.map((d,i)=>`<div class="card" style="border-color:${i===weekDay?'var(--green)':'var(--line)'}"><div class="st"><h2>${d.label} · ${dt(d.date)}</h2>${B(d.done.length+' done · '+d.pending.length+' to cut',d.minutes>(+S.set.dailyHours||8)*60?'w':'')}</div><div class="small">${d.pending.length?`~${d.minutes} min total · ~${d.route.miles.toFixed(1)} mi driving`:'No remaining stops'}${d.minutes>(+S.set.dailyHours||8)*60?' · Over crew hours':''}</div>${d.route.order.map((p,j)=>`<div class="sl"><span><strong>${j+1}.</strong> ${esc(p.name)} ${coord(p)?'':B('Add map address','w')}<br><span class="small">~${eta(p)} min mowing · ${p.visits[0]?'last '+dt(p.visits[0].date):'first service'}</span>${weatherNoteFor(w.plan,p)}</span><select aria-label="Move ${esc(p.name)} to a day" style="max-width:94px" onchange="weekMove('${esc(p.id)}',this.value)">${DAY.map((name,k)=>`<option value="${k}"${k===i?' selected':''}${!weekOffset&&k<dayDiff(today(),w.key)?' disabled':''}>${name}</option>`).join('')}</select></div>`).join('')}${d.done.map(p=>`<div class="sl small">✓ ${esc(p.name)} · logged</div>`).join('')}<button class="btn sm" style="margin-top:10px" onclick="showWeekDay(${i});routeWeekDay()">View day's route</button></div>`).join('')}</div>
<div class="card" style="margin-top:16px"><div class="st"><h2>Preferred service day</h2><span class="small">Automatic keeps nearby jobs together</span></div><div class="grid three">${S.bp.map(p=>`<label class="small">${esc(p.name)}<select style="display:block;width:100%;margin-top:4px" onchange="weekPreference('${esc(p.id)}',this.value)"><option value="auto"${p.serviceDay==null?' selected':''}>Automatic</option>${DAY.map((day,d)=>`<option value="${d}"${p.serviceDay===d?' selected':''}>${day}</option>`).join('')}</select></label>`).join('')}</div></div>
<div class="grid two"><div class="card"><div class="st"><h2>${selected.label} route map</h2><span class="small">${rt?(rt.src==='road'?'Road routing (OSRM)':'Straight-line estimate'):'Select a day to see its route'}</span></div><div class="map" id="rmap" style="height:460px"></div></div>
<div class="card"><div class="st"><h2>Route stops · ${selected.label}</h2></div>${S.bp.map(p=>`<label class="sl" style="cursor:pointer"><span><input type="checkbox" style="width:auto" ${rsel[p.id]?'checked':''} ${coord(p)?'':'disabled'} onchange="rsel['${esc(p.id)}']=this.checked"> ${esc(p.name)}</span><span>${coord(p)?dueB(p):B('No address','w')}</span></label>`).join('')}
<div class="form" style="margin-top:12px"><label>Start from<select onchange="rst=this.value"><option value="me"${rst=='me'?' selected':''}>My current location</option><option value="first"${rst=='first'?' selected':''}>First selected stop</option>${S.set.depot?`<option value="depot"${rst=='depot'?' selected':''}>Crew start address</option>`:''}</select></label></div>
<div class="actions" style="flex-wrap:wrap;justify-content:flex-start"><button class="btn primary" onclick="optRoute()">⚡ Optimize route on roads</button><button class="btn" onclick="gmapsLink()">Open in Google Maps</button><button class="btn" onclick="trackMe()">📍 ${rwatch!=null?'Stop tracking':'Track me'}</button></div><div class="small" style="margin-top:8px">Only properties with map coordinates can be routed. Check the selected stops before optimizing. The daily schedule remains saved when you preview a route.</div></div></div>${rt?rtSum():''}`}
function gmapsLink(){if(!rt)return toast('Optimize a route first');const c=rt.ord.map(q=>q.lat+','+q.lng);if(c.length<2)return toast('Need at least 2 points');window.open(`https://www.google.com/maps/dir/?api=1&origin=${c[0]}&destination=${c[c.length-1]}${c.length>2?'&waypoints='+c.slice(1,-1).slice(0,9).join('%7C'):''}&travelmode=driving`,'_blank')}
function drawRouteMap(){const el=$('rmap');if(maps.rmap){maps.rmap.remove();delete maps.rmap}if(!el||typeof L==='undefined')return;const m=L.map('rmap'),all=[];maps.rmap=m;
L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Tiles © Esri'}).addTo(m);
const ic=(n,c)=>L.divIcon({className:'',html:`<div style="background:${c};color:#fff;width:26px;height:26px;border-radius:50%;display:grid;place-items:center;font:700 12px sans-serif;border:2px solid #fff">${n}</div>`,iconSize:[26,26]});
if(rt){L.polyline(rt.geo,{color:'#2563eb',weight:5,opacity:.8}).addTo(m);rt.ord.forEach((q,i)=>{L.marker([q.lat,q.lng],{icon:ic(q.me||q.depot?'●':i+1,q.me||q.depot?'#e11d48':'#1f6b45')}).bindTooltip(q.me||q.depot?'Start':q.p.name).addTo(m);all.push([q.lat,q.lng])})}
else S.bp.filter(p=>p.lat).forEach(p=>{L.marker([p.lat,p.lng],{icon:ic('•','#6b756e')}).bindTooltip(p.name).addTo(m);all.push([p.lat,p.lng])});
all.length?m.fitBounds(all,{padding:[30,30],maxZoom:16}):m.setView([39.5,-98.35],4);
if(rme)m._me=L.circleMarker(rme,{radius:8,color:'#fff',fillColor:'#2563eb',fillOpacity:1,weight:3}).addTo(m)}
function trackMe(){if(rwatch!=null){navigator.geolocation.clearWatch(rwatch);rwatch=null;rme=null;toast('Tracking off');renderRoute();return drawRouteMap()}if(!navigator.geolocation)return toast('Location not supported on this device');
rwatch=navigator.geolocation.watchPosition(p=>{rme=[p.coords.latitude,p.coords.longitude];const m=maps.rmap;if(m){if(m._me)m.removeLayer(m._me);m._me=L.circleMarker(rme,{radius:8,color:'#fff',fillColor:'#2563eb',fillOpacity:1,weight:3}).addTo(m)}},()=>{rwatch=null;toast('Location permission denied')},{enableHighAccuracy:true});toast('Tracking your position');renderRoute();drawRouteMap()}
let renderRepairTried=false;function render(){try{if(S.mode==='cust'){renderCustomer();renderPortal()}else if(S.mode==='crew'){renderCrew();renderMap();renderHist();renderWx();renderRoute()}else{renderDash();renderMap();renderHist();renderCust();renderPro();renderAn();renderSet();renderWx();renderHealth();renderPortal();renderRoute()}initMaps();if($('route').classList.contains('active'))drawRouteMap();else if(maps.rmap){maps.rmap.remove();delete maps.rmap}if(S.mode!=='cust'&&$('weather').classList.contains('active'))loadWx('wx_w');if(S.mode==='biz'&&$('health').classList.contains('active'))loadHealthPlan();renderRepairTried=false}catch(e){console.error('Render failed',e);if(!renderRepairTried){renderRepairTried=true;try{fix();save();return render()}catch(repairErr){console.error('Automatic state repair failed',repairErr)}}const active=document.querySelector('.view.active')||document.querySelector('.view');if(active)active.innerHTML=`<div class="card"><h2>TurfOS could not display this view</h2><p class="small">Your customer, billing, and service data are still stored. TurfOS attempted to repair older saved property data automatically. Try another section or refresh the affected property map.</p><div class="actions"><button class="btn primary" onclick="go('dashboard');renderRepairTried=false;render()">Return to Dashboard</button><button class="btn" onclick="go('map');renderRepairTried=false;render()">Open Property Map</button></div><details style="margin-top:12px"><summary class="small">Technical detail</summary><div class="small" style="margin-top:6px">${esc(e?.message||String(e))}</div></details></div>`}}

setInterval(()=>{if(S.st&&S.st.type){loadWx('wx_w');loadHealthPlan()}},3e5);
function isStandalone(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true}
function showInstallBanner(){if(isStandalone()||localStorage.getItem('turfos-install-dismissed')==='1')return;const b=$('installBanner');if(b)b.classList.add('on')}
async function installTurfOS(){if(isStandalone())return toast('TurfOS is already installed');if(beforeInstallPrompt){beforeInstallPrompt.prompt();const r=await beforeInstallPrompt.userChoice;beforeInstallPrompt=null;$('installBanner')?.classList.remove('on');if(r.outcome==='accepted')toast('TurfOS installed');return}const isiOS=/iphone|ipad|ipod/i.test(navigator.userAgent);openM(`<h2>Install TurfOS</h2><p class="small">${isiOS?'On iPhone/iPad: tap the Share button in Safari, then choose <strong>Add to Home Screen</strong>.':'Open this hosted TurfOS site in Chrome or Edge, open the browser menu, and choose <strong>Install app</strong> or <strong>Add to Home screen</strong>.'}</p><div class="actions"><button class="btn primary" onclick="closeM()">Got it</button></div>`)}
function dismissInstall(){localStorage.setItem('turfos-install-dismissed','1');$('installBanner')?.classList.remove('on')}
addEventListener('beforeinstallprompt',e=>{e.preventDefault();beforeInstallPrompt=e;showInstallBanner()});addEventListener('appinstalled',()=>{$('installBanner')?.classList.remove('on');toast('TurfOS installed')});addEventListener('online',()=>{if(BIZ_ACCOUNT){setSyncState('saving');pullCloudWorkspace(true).then(()=>syncCloudWorkspace())}});addEventListener('offline',()=>setSyncState('offline'));document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&BIZ_ACCOUNT)pullCloudWorkspace(true)});setInterval(()=>{if(BIZ_ACCOUNT&&document.visibilityState==='visible')pullCloudWorkspace(false)},180000);
const publicMode=new URLSearchParams(location.search).get('mode');
if(['biz','crew','cust'].includes(publicMode))S.mode=publicMode;

async function boot(){save();if(S.mode==='biz'||S.mode==='crew'){const ok=await loadBusinessSession();if(!ok)return}else if(S.mode==='cust'){const ok=await loadCustomerSession();if(!ok)return}else hideBusinessAuth();buildNav();updateBusinessBrand();go(S.mode==='cust'?'customer':S.mode==='crew'?'crew':'dashboard');render();if(S.activeCut&&S.mode!=='cust')tickCut();if(S.mode!=='cust'&&cur()?.parcel&&cur().buildingDataVersion!==BUILDING_DATA_VERSION)findObstacles(cur())}
boot();
if('serviceWorker' in navigator)addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
try{navigator.storage&&navigator.storage.persist&&navigator.storage.persist()}catch(e){}
